const directions: Direction[] = ['up', 'left', 'right', 'down'];
const folder = socialSources[0].url;
export const socialBulkEditions = editions.map(e => ({ key: e.key, name: e.name, source: socialSources[e.file] }));

export const socialBulkCards: SwipeCard[] = editions.flatMap(edition => {
  const src = socialSources[edition.file];
  return edition.rows.map(([question, choices, explanation, page], index) => ({
    id: `social-bulk-${edition.key}-${String(index + 1).padStart(3, '0')}`,
    topic: edition.name, question,
    answers: Object.fromEntries(directions.map((direction, i) => [direction, choices[i]])) as Record<Direction, string>,
    correct: 'up' as Direction, explanation,
    source: { title: src.title, url: src.url ?? folder, page, label: src.label, teacher: '성신제T' },
  }));
});

const noteOf = (edition: Edition) => `성신제T 학습지 ${edition.key} · ${socialSources[edition.file].label}`;
const rubrics: WrittenQuestion[] = editions.flatMap(edition => edition.written.map((q, index) => ({
  ...q, id: `social-bulk-${edition.key}-written-${String(index + 1).padStart(3, '0')}`, topic: edition.name, sourceNote: noteOf(edition),
})));

// 3.5.1 연습 방식(단답형·이유 서술)을 뭉탱이에도: 답이 한 낱말·구로 떨어지는 카드만 고른다
// (짝짓기 A–B, '옳지 않은 것', 연결 문제는 쓰기로 바꾸면 답이 여러 개라 뺀다).
const writable = (card: SwipeCard) => !/[–]/.test(card.answers[card.correct]) && !/(않은|아닌|않는|않을|해당하지|알맞은 것|알맞게)/.test(card.question);
const practiceOf = (card: SwipeCard, kind: 'short' | 'written'): WrittenQuestion => {
  const answer = card.answers[card.correct];
  const edition = editions.find(e => e.name === card.topic)!;
  return kind === 'short'
    ? { id: `practice-short-${card.id}`, topic: card.topic, question: `${card.question} (답을 하나만 쓰세요.)`, modelAnswer: answer, criteria: [`정답: ${answer}`], sourceNote: noteOf(edition) }
    : { id: `practice-written-${card.id}`, topic: card.topic, question: `${card.question} 답과 그 이유를 연결하여 서술하시오.`, modelAnswer: `${answer}. ${card.explanation}`, criteria: [`결론: ${answer}`, `근거: ${card.explanation}`], sourceNote: noteOf(edition) };
};
const practiceCards = socialBulkCards.filter(writable);
// 단답형은 정확히 같은 답을 쓰게 되므로 짧은 낱말·이름만(두 어절 이하, 10자 이하). 서술형은 고른 카드 전부.
const shortable = (card: SwipeCard) => { const a = card.answers[card.correct]; return Array.from(a).length <= 10 && a.split(' ').length <= 2 && !/옳은 것/.test(card.question); };
export const socialBulkPractice = { short: practiceCards.filter(shortable).map(card => practiceOf(card, 'short')), written: practiceCards.map(card => practiceOf(card, 'written')) };

export const socialBulkWritten: WrittenQuestion[] = [...rubrics, ...socialBulkPractice.short, ...socialBulkPractice.written];
